import{_ as t,a0 as l,w as o,s as c,ao as d,I as i,x as n,a1 as p,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"4 步打包一个新的 Python 模块 | LCTT x X-CMD","titleTemplate":false,"description":"4 步打包一个新的 Python 模块 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"4 步打包一个新的 Python 模块 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"4 步打包一个新的 Python 模块 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220630 Package a new Python module in 4 steps","title":"4 步打包一个新的 Python 模块","tag":"202209","desc":""},"relativePath":"202209/20220630 Package a new Python module in 4 steps.md","filePath":"[post].md"}'),r={name:"202209/20220630 Package a new Python module in 4 steps.md"};function h(g,s,u,k,b,y){const a=l("Link");return o(),c("div",null,[s[15]||(s[15]=d(`<h1 id="_4-步打包一个新的-python-模块" tabindex="-1">4 步打包一个新的 Python 模块 <a class="header-anchor" href="#_4-步打包一个新的-python-模块" aria-label="Permalink to “4 步打包一个新的 Python 模块”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202209/14/155051kzjuzhzvmllmv2b5.jpg" alt=""></p><blockquote><p>pyp2rpm 使得创建 RPM 包的过程更加自动化。</p></blockquote><p>当你安装一个应用程序时，你通常是在安装一个软件包，其中包含应用程序的可执行代码和重要文件，如文档、图标等。在 Linux上，软件一般被打包成 RPM 或 DEB 等格式，用户只要通过 <code>dnf</code> 或者 <code>apt</code> 等命令就可以进行安装了，这取决于你使用的 Linux 发行版。然而几乎每天都有新的 Python 模块发布，因此你很容易遇到一个尚未打包的 Python 模块。这就是 <code>pyp2rpm</code> 存在的意义了。</p><p>最近我在尝试安装一个叫 <code>python-concentration</code> 的模块，但是进展并不太顺利：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install python-concentration</span></span>
<span class="line"><span>Updating Subscription Management repositories.</span></span>
<span class="line"><span>Last metadata expiration check: 1:23:32 ago on Sat 11 Jun 2022 06:37:25.</span></span>
<span class="line"><span>No match for argument: python-concentration</span></span>
<span class="line"><span>Error: Unable to find a match: python-concentration</span></span></code></pre></div><p>虽然这是一个发布在 PyPi 的包，但它仍不能被打包成 RPM 包。好消息是你可以使用 <code>pyp2rpm</code> 以一个相对简单的过程将它打包成 RPM 包。</p><p>首先你需要设置两个目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir rpmbuild</span></span>
<span class="line"><span>$ cd rpmbuild &amp;&amp; mkdir SPECS</span></span></code></pre></div><p>像这样去安装 <code>pyp2rpm</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install pyp2rpm</span></span></code></pre></div><h3 id="_1、生成-spec-文件" tabindex="-1">1、生成 spec 文件 <a class="header-anchor" href="#_1、生成-spec-文件" aria-label="Permalink to “1、生成 spec 文件”">​</a></h3><p>RPM 包的基础是一种 spec 文件，这个文件包含你创建这个包的所有信息，如所需的依赖关系、应用的版本号、安装的文件等信息。当指向某个 Python 模块时，<code>pyp2rpm</code> 会为它构建一个 spec 文件，你可以用它来创建 RPM 包。</p><p>下面以 <code>python-concentration</code> 为例演示如何构建一个 spec 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pyp2rpm concentration &gt; ~/rpmbuild/SPECS/concentration.spec</span></span></code></pre></div><p>下面是它生成的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Created by pyp2rpm-3.3.8</span></span>
<span class="line"><span>%global pypi_name concentration</span></span>
<span class="line"><span>%global pypi_version 1.1.5</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Name:           python-%{pypi_name}</span></span>
<span class="line"><span>Version:        %{pypi_version}</span></span>
<span class="line"><span>Release:        1%{?dist}</span></span>
<span class="line"><span>Summary:        Get work done when you need to, goof off when you don&#39;t</span></span>
<span class="line"><span></span></span>
<span class="line"><span>License:        None</span></span>
<span class="line"><span>URL:            None</span></span>
<span class="line"><span>Source0:        %{pypi_source}</span></span>
<span class="line"><span>BuildArch:      noarch</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BuildRequires:  python3-devel</span></span>
<span class="line"><span>BuildRequires:  python3dist(setuptools)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>%description</span></span>
<span class="line"><span>Concentration [![PyPI version]( [![Test Status]( [![Lint Status]( [![codecov](</span></span>
<span class="line"><span></span></span>
<span class="line"><span>%package -n     python3-%{pypi_name}</span></span>
<span class="line"><span>Summary:        %{summary}</span></span>
<span class="line"><span>%{?python_provide:%python_provide python3-%{pypi_name}}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Requires:       (python3dist(hug) &gt;= 2.6.1 with python3dist(hug) &lt; 3~~)</span></span>
<span class="line"><span>Requires:       python3dist(setuptools)</span></span>
<span class="line"><span>%description -n python3-%{pypi_name}</span></span>
<span class="line"><span>Concentration [![PyPI version]( [![Test Status]( [![Lint Status]( [![codecov](</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>%prep</span></span>
<span class="line"><span>%autosetup -n %{pypi_name}-%{pypi_version}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>%build</span></span>
<span class="line"><span>%py3_build</span></span>
<span class="line"><span></span></span>
<span class="line"><span>%install</span></span>
<span class="line"><span>%py3_install</span></span>
<span class="line"><span></span></span>
<span class="line"><span>%files -n python3-%{pypi_name}</span></span>
<span class="line"><span>%license LICENSE</span></span>
<span class="line"><span>%doc README.md</span></span>
<span class="line"><span>%{_bindir}/concentration</span></span>
<span class="line"><span>%{python3_sitelib}/%{pypi_name}</span></span>
<span class="line"><span>%{python3_sitelib}/%{pypi_name}-%{pypi_version}-py%{python3_version}.egg-info</span></span>
<span class="line"><span></span></span>
<span class="line"><span>%changelog</span></span>
<span class="line"><span>*  - 1.1.5-1</span></span>
<span class="line"><span>- Initial package.</span></span></code></pre></div><h3 id="_2、运行-rpmlint" tabindex="-1">2、运行 rpmlint <a class="header-anchor" href="#_2、运行-rpmlint" aria-label="Permalink to “2、运行 rpmlint”">​</a></h3><p>为了确保 spec 文件符合标准，你需要对文件使用 <code>rpmlint</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpmlint ~/rpmbuild/SPEC/concentration.spec</span></span>
<span class="line"><span>error: bad date in %changelog: - 1.1.5-1</span></span>
<span class="line"><span>0 packages and 1 specfiles checked; 0 errors, 0 warnings.</span></span></code></pre></div><p>看起来更新日志（<code>%changelog</code>）需要记录日期。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>%changelog</span></span>
<span class="line"><span>* Sat Jun 11 2022 Tux &lt;tux@example.com&gt; - 1.1.5-1</span></span></code></pre></div><p>再次运行 <code>rpmint</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpmlint ~/rpmbuild/SPEC/concentration.spec</span></span>
<span class="line"><span>0 packages and 1 specfiles checked; 0 errors, 0 warnings.</span></span></code></pre></div><p>成功！</p><h3 id="_3、下载源码" tabindex="-1">3、下载源码 <a class="header-anchor" href="#_3、下载源码" aria-label="Permalink to “3、下载源码”">​</a></h3><p>你需要下载好打包的代码才能进一步构建 RPM 包。一种简单的方式是解析你的 spec 文件以获取源码的网址。</p><p>首先，通过 <code>dnf</code> 安装 <code>spectool</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install spectool</span></span></code></pre></div><p>然后通过 <code>spectool</code> 来下载源码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ~/rpmbuild</span></span>
<span class="line"><span>$ spectool -g -R SPEC/concentration.spec</span></span>
<span class="line"><span>Downloading: https://files.pythonhosted.org/...concentration-1.1.5.tar.gz</span></span>
<span class="line"><span>   6.0 KiB / 6.0 KiB    [=====================================]</span></span>
<span class="line"><span>Downloaded: concentration-1.1.5.tar.gz</span></span></code></pre></div><p>这样就创建了一个 <code>SOURCES</code> 目录并将源码放入其中。</p><h3 id="_4、构建源软件包" tabindex="-1">4、构建源软件包 <a class="header-anchor" href="#_4、构建源软件包" aria-label="Permalink to “4、构建源软件包”">​</a></h3><p>现在你已经验证过 spec 文件了，接下来就可以通过 <code>rpmbuild</code> 构建源软件包了。如果你还没有安装 <code>rpmbuild</code>，你也可以通过 <code>dnf</code> 安装 <code>rpm-build</code> 包（或者在使用 <code>rpmbuild</code> 命令时根据终端的的提示进行安装）。</p><p>参数 <code>-bs</code> 表示构建源软件包。添加这个参数会产生一个 src.rpm 文件，这是一个用于为特定架构重新构建的通用包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpmbuild -bs SPECS/concentration.spec</span></span>
<span class="line"><span>Wrote: ~/rpmbuild/SRPMS/python-concentration-1.1.5-1.el9.src.rpm</span></span></code></pre></div><p>为你的系统构建一个可安装的 RPM 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpmbuild –rebuild SRPMS/python-concentration-1.1.5-1.el9.src.rpm</span></span>
<span class="line"><span>error: Failed build dependencies:</span></span>
<span class="line"><span>        python3-devel is needed by python-concentration-1.1.5-1.el9.noarch</span></span></code></pre></div><p>看起来这个包需要安装 Python 的开发库才能继续构建。安装它们以继续构建。这一次，构建成功了，并且渲染了更多的输出（为了清楚起见，我在这里简略了输出）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install python3-devel -y</span></span>
<span class="line"><span>$ rpmbuild –rebuild SRPMS/python-concentration-1.1.5-1.el9.src.rpm</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>Executing(--clean): /bin/sh -e /var/tmp/rpm-tmp.TYA7l2</span></span>
<span class="line"><span>+ umask 022</span></span>
<span class="line"><span>+ cd /home/bogus/rpmbuild/BUILD</span></span>
<span class="line"><span>+ rm -rf concentration-1.1.5</span></span>
<span class="line"><span>+ RPM_EC=0</span></span>
<span class="line"><span>++ jobs -p</span></span>
<span class="line"><span>+ exit 0</span></span></code></pre></div><p>你的 RPM 包现在已经构建在 <code>RPMS</code> 子目录下，像平常一样使用 <code>dnf</code> 安装它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install RPMS/noarch/python3-concentration*rpm</span></span></code></pre></div><h3 id="为什么不使用-pypi" tabindex="-1">为什么不使用 PyPi？ <a class="header-anchor" href="#为什么不使用-pypi" aria-label="Permalink to “为什么不使用 PyPi？”">​</a></h3><p>通常情况下我们并不需要将 Python 模块打包成 RPM 包。通过 PyPi 来安装模块也是可以接受的，但是 PyPi 会安装额外的包管理器对你的模块进行检查和更新。当你使用 <code>dnf</code> 来安装 RPM 包时，你在安装完成时就能够获取到完整的安装列表。有了 <code>pyp2rpm</code> 之后，这个过程就变得快速、简单且自动化了。</p><hr>`,45)),i("p",null,[s[1]||(s[1]=n("via: ",-1)),p(a,{href:"https://opensource.com/article/22/6/package-python-module-rpm"},{default:e(()=>[...s[0]||(s[0]=[n("https://opensource.com/article/22/6/package-python-module-rpm",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=n("作者：",-1)),p(a,{href:"https://opensource.com/users/sumantro"},{default:e(()=>[...s[2]||(s[2]=[n("Sumantro Mukherjee",-1)])]),_:1}),s[7]||(s[7]=n(" 选题：",-1)),p(a,{href:"https://github.com/lkxed"},{default:e(()=>[...s[3]||(s[3]=[n("lkxed",-1)])]),_:1}),s[8]||(s[8]=n(" 译者：",-1)),p(a,{href:"https://github.com/Return7g"},{default:e(()=>[...s[4]||(s[4]=[n("Return7g",-1)])]),_:1}),s[9]||(s[9]=n(" 校对：",-1)),p(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=n("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原创编译，",-1)),p(a,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[n("Linux中国",-1)])]),_:1}),s[14]||(s[14]=n(" 荣誉推出",-1))])])}const C=t(r,[["render",h]]);export{P as __pageData,C as default};
